    "version": 2,
    "name": "oasis-v3-money-machine",
    "alias": ["oasis-v3.com", "www.oasis-v3.com"],
    "description": "OASIS v3 - Ultra-Lightweight AI Superintelligence Ecosystem | $50K+/month Revenue Target",
    "build": {
        "env": {
            "NEXT_PUBLIC_HF_SPACES_URL": "@hf_spaces_url",
            "NEXT_PUBLIC_SUPABASE_URL": "@supabase_url",
            "NEXT_PUBLIC_SUPABASE_ANON_KEY": "@supabase_anon_key",
