            "NEXT_PUBLIC_ANALYTICS_ID": "@google_analytics_id",
            "NEXT_PUBLIC_HOTJAR_ID": "@hotjar_id"
        }
    },
    "functions": {
        "pages/api/**/*.js": {
            "runtime": "nodejs18.x",
            "maxDuration": 30,
            "memory": 1024
        }
    },
    "redirects": [
        {
            "source": "/demo",
            "destination": "/#ai-processing",
            "permanent": False
        },
        {
            "source": "/revenue",
            "destination": "/#revenue-dashboard",
            "permanent": False
        },
        {
            "source": "/termux", 
            "destination": "/#termux-setup",
            "permanent": False
        }
    ],
    "rewrites": [
        {
            "source": "/api/hf/(.*)",
            "destination": "https://oasis-v3-ai-processing-hub.hf.space/api/$1"
        }
    ],
    "headers": [
        {
            "source": "/(.*)",
            "headers": [
                {
                    "key": "X-Frame-Options",
                    "value": "DENY"
                },
                {
                    "key": "X-Content-Type-Options", 
                    "value": "nosniff"
                },
                {
                    "key": "Referrer-Policy",
                    "value": "origin-when-cross-origin"
                }
            ]
        }
    ]
}

