zapier_automation = """# Zapier Automation Workflows for OASIS v3
# Automates business processes, notifications, and integrations

import json
import requests
from typing import Dict, Any, List

class ZapierAutomation:
    def __init__(self, webhook_urls: Dict[str, str]):
        self.webhooks = webhook_urls

    def trigger_new_user_workflow(self, user_data: Dict[str, Any]):
        \"\"\"
        Trigger when new user signs up
        - Send welcome email
        - Create Slack notification
        - Add to CRM
        \"\"\"
        payload = {
            'event_type': 'new_user_signup',
            'user_id': user_data.get('id'),
            'email': user_data.get('email'),
            'signup_date': user_data.get('created_at'),
            'source': 'oasis-v3',
            'revenue_potential': 0
        }

        return self._send_webhook('new_user', payload)

    def trigger_subscription_upgrade(self, user_data: Dict[str, Any], subscription_data: Dict[str, Any]):
        \"\"\"
        Trigger when user upgrades subscription
        - Send congratulations email
        - Notify sales team
        - Update revenue projections
        \"\"\"
        payload = {
            'event_type': 'subscription_upgrade',
            'user_id': user_data.get('id'),
            'email': user_data.get('email'),
            'from_tier': subscription_data.get('previous_tier', 'free'),
            'to_tier': subscription_data.get('new_tier'),
            'monthly_revenue': subscription_data.get('amount'),
            'upgrade_date': subscription_data.get('created_at'),
            'estimated_annual_value': subscription_data.get('amount', 0) * 12
        }

        return self._send_webhook('subscription_upgrade', payload)

    def trigger_revenue_milestone(self, milestone_data: Dict[str, Any]):
        \"\"\"
