        \"\"\"
        Trigger when user completes Termux setup
        - Send setup success confirmation
        - Provide next steps guide
        - Track onboarding completion
        \"\"\"
        payload = {
            'event_type': 'termux_setup_complete',
            'user_id': setup_data.get('user_id'),
            'email': setup_data.get('email'),
            'setup_duration': setup_data.get('duration_minutes'),
            'device_type': setup_data.get('device_type'),
