            'next_steps': [
                'Start using AI APIs',
                'Explore revenue features',
                'Join community forum'
            ]
        }

        return self._send_webhook('termux_setup_complete', payload)

    def _send_webhook(self, webhook_type: str, payload: Dict[str, Any]) -> bool:
        \"\"\"Send webhook to Zapier\"\"\"
        if webhook_type not in self.webhooks:
            print(f"Warning: No webhook URL configured for {webhook_type}")
            return False

        try:
            response = requests.post(
                self.webhooks[webhook_type],
                json=payload,
                headers={'Content-Type': 'application/json'},
                timeout=10
            )
            response.raise_for_status()
            print(f"Successfully triggered {webhook_type} webhook")
            return True

        except requests.exceptions.RequestException as e:
            print(f"Failed to trigger {webhook_type} webhook: {e}")
            return False

