stripe_integration = '''/*
 * OASIS v3 Stripe Integration
 * Production-ready payment processing for $50K+/month revenue
 * 
 * Features:
 * - Subscription management (Basic, Professional, Enterprise)  
 * - Usage-based billing for API requests
 * - Webhook handling for real-time revenue tracking
 * - Automated invoicing and payment collection
 */

import Stripe from 'stripe';
import { createClient } from '@supabase/supabase-js';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY, {
  apiVersion: '2023-10-16',
});

const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_KEY
);

// Pricing tiers matching OASIS v3 revenue model
export const PRICING_TIERS = {
  basic: {
    name: 'Basic',
    price_per_request: 0.01, // $0.01 per request
    monthly_quota: 50000,
    stripe_price_id: 'price_basic_monthly', // Set in Stripe dashboard
  },
  professional: {
    name: 'Professional', 
    price_per_request: 0.02, // $0.02 per request
    monthly_quota: 100000,
    stripe_price_id: 'price_professional_monthly',
  },
  enterprise: {
    name: 'Enterprise',
    price_per_request: 0.03, // $0.03 per request  
    monthly_quota: 250000,
    stripe_price_id: 'price_enterprise_monthly',
  }
};

/**
 * Create Stripe customer and subscription
 */
export async function createStripeCustomer(user) {
  try {
    // Create Stripe customer
    const customer = await stripe.customers.create({
      email: user.email,
      metadata: {
        user_id: user.id,
        subscription_tier: user.subscription_tier || 'basic',
        oasis_version: '3.0.0'
      }
    });

    // Create subscription based on tier
    const tier = PRICING_TIERS[user.subscription_tier || 'basic'];

    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{
        price: tier.stripe_price_id,
      }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent'],
      metadata: {
        user_id: user.id,
        tier: user.subscription_tier || 'basic',
      }
    });

    // Update user with Stripe customer ID
    await supabase
      .from('users')
      .update({ 
        stripe_customer_id: customer.id,
        subscription_status: 'pending'
      })
      .eq('id', user.id);

    return {
      subscription_id: subscription.id,
      client_secret: subscription.latest_invoice.payment_intent.client_secret,
      customer_id: customer.id
    };

  } catch (error) {
    console.error('Stripe customer creation error:', error);
    throw error;
  }
}

/**
 * Process usage-based billing for API requests
 */
export async function processUsageBilling(userId, requests) {
  try {
    // Get user's Stripe customer ID and tier
    const { data: user } = await supabase
      .from('users')
      .select('stripe_customer_id, subscription_tier')
      .eq('id', userId)
      .single();

    if (!user?.stripe_customer_id) {
      throw new Error('User has no Stripe customer ID');
    }

    const tier = PRICING_TIERS[user.subscription_tier];
    const totalAmount = Math.round(requests.length * tier.price_per_request * 100); // Convert to cents

    // Create usage record for billing
    const usageRecord = await stripe.subscriptionItems.createUsageRecord(
      user.stripe_subscription_item_id, // Set during subscription creation
      {
        quantity: requests.length,
        timestamp: Math.floor(Date.now() / 1000),
        action: 'increment'
      }
    );

    // Log revenue in Supabase
    for (const request of requests) {
      await supabase
        .from('api_requests')
        .update({
          final_price: tier.price_per_request,
          billed_at: new Date().toISOString()
        })
        .eq('id', request.id);
    }

    // Record revenue event for analytics
    await recordRevenueEvent({
      user_id: userId,
      amount: totalAmount / 100, // Back to dollars
      requests_count: requests.length,
      tier: user.subscription_tier,
      stripe_usage_record_id: usageRecord.id
    });

    return usageRecord;

  } catch (error) {
    console.error('Usage billing error:', error);
    throw error;
  }
}

/**
 * Handle Stripe webhooks for real-time revenue tracking
 */
export async function handleStripeWebhook(event) {
  try {
    switch (event.type) {
      case 'customer.subscription.created':
        await handleSubscriptionCreated(event.data.object);
        break;

      case 'customer.subscription.updated':
        await handleSubscriptionUpdated(event.data.object);
        break;

      case 'invoice.payment_succeeded':
        await handlePaymentSucceeded(event.data.object);
        break;

      case 'invoice.payment_failed':
        await handlePaymentFailed(event.data.object);
        break;

      case 'customer.subscription.deleted':
        await handleSubscriptionDeleted(event.data.object);
        break;

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    return { received: true };

  } catch (error) {
    console.error('Webhook handling error:', error);
    throw error;
  }
}

async function handleSubscriptionCreated(subscription) {
  const userId = subscription.metadata.user_id;

  await supabase
    .from('users')
    .update({
      subscription_status: 'active',
      last_payment_at: new Date().toISOString()
    })
    .eq('id', userId);

  await recordRevenueEvent({
    user_id: userId,
    event_type: 'subscription_created',
    tier: subscription.metadata.tier,
    stripe_subscription_id: subscription.id
  });
}

async function handlePaymentSucceeded(invoice) {
  const customerId = invoice.customer;

  // Get user by Stripe customer ID
  const { data: user } = await supabase
    .from('users')
    .select('id, subscription_tier')
    .eq('stripe_customer_id', customerId)
    .single();

  if (user) {
    await supabase
      .from('users')
      .update({
        subscription_status: 'active',
        last_payment_at: new Date().toISOString()
      })
      .eq('id', user.id);

    await recordRevenueEvent({
      user_id: user.id,
      event_type: 'payment_succeeded',
      amount: invoice.amount_paid / 100, // Convert from cents
      tier: user.subscription_tier,
      stripe_invoice_id: invoice.id
    });
  }
}

async function recordRevenueEvent(eventData) {
  await supabase
    .from('system_events')
    .insert({
      event_type: 'revenue_event',
      description: `Revenue event: ${eventData.event_type || 'usage_billing'}`,
      metadata: eventData,
      severity: 'info'
    });
}

/**
 * Get revenue analytics from Stripe
 */
export async function getStripeRevenue(startDate, endDate) {
  try {
    const charges = await stripe.charges.list({
      created: {
        gte: Math.floor(startDate.getTime() / 1000),
        lte: Math.floor(endDate.getTime() / 1000)
      },
      limit: 100
    });

    const totalRevenue = charges.data
      .filter(charge => charge.paid && !charge.refunded)
      .reduce((sum, charge) => sum + charge.amount, 0) / 100; // Convert from cents

    return {
      total_revenue: totalRevenue,
      transaction_count: charges.data.length,
      period_start: startDate,
      period_end: endDate
    };

  } catch (error) {
    console.error('Stripe revenue fetch error:', error);
    throw error;
  }
}

/**
 * Upgrade/downgrade subscription tier
 */
export async function changeSubscriptionTier(userId, newTier) {
  try {
    const { data: user } = await supabase
      .from('users')
      .select('stripe_customer_id')
      .eq('id', userId)
      .single();

    const subscriptions = await stripe.subscriptions.list({
      customer: user.stripe_customer_id,
      status: 'active'
    });

    if (subscriptions.data.length > 0) {
      const subscription = subscriptions.data[0];
      const newPriceId = PRICING_TIERS[newTier].stripe_price_id;

      await stripe.subscriptions.update(subscription.id, {
        items: [{
          id: subscription.items.data[0].id,
          price: newPriceId,
        }],
        metadata: {
          ...subscription.metadata,
          tier: newTier
        }
      });

      // Update in Supabase
      await supabase
        .from('users')
        .update({ subscription_tier: newTier })
        .eq('id', userId);

      await recordRevenueEvent({
        user_id: userId,
        event_type: 'tier_change',
        old_tier: user.subscription_tier,
        new_tier: newTier
      });
    }

  } catch (error) {
    console.error('Subscription tier change error:', error);
    throw error;
  }
}

